section.programlisting:
{
    "version": "0.2.0",
    "configurations": [
        {
            "type": "scaly",
            "request": "launch",
            "name": "Debug the open Scaly file",
            "source": "${file}"
        }
    ]
}

{
    "version": "0.2.0",
    "configurations": [
        {
            "type": "scaly",
            "request": "launch",
            "name": "Debug greet with arguments",
            "source": "${workspaceFolder}/greet.scaly",
            "args": ["Ada", "Grace"],
            "env": { "GREETING": "Hello" },
            "cwd": "${workspaceFolder}"
        },
        {
            "type": "scaly",
            "request": "launch",
            "name": "Debug the built server",
            "program": "${workspaceFolder}/build/server",
            "args": ["--port", "8080"]
        }
    ]
}

{
    "version": "0.2.1",
    "tasks": [
        {
            "taskLabel": "scaly build",
            "appliesTo": "*.scaly",
            "type": "launch",
            "contextType": "build",
            "command": "scaly",
            "args": [ "build", "-g", "${file}",
                      "-o", "${fileDirname}\\${fileBasenameNoExtension}.exe" ]
        }
    ]
}

{
    "version": "0.2.1",
    "defaults": {},
    "configurations": [
        {
            "type": "default",
            "project": "area.exe",
            "name": "area.exe",
            "args": [ "Ada", "Grace" ],
            "currentDir": "${workspaceRoot}",
            "env": { "GREETING": "Hello" }
        }
    ]
}

define Counter(var value: int) { procedure increment(mutable this) value := value + 1
function get(this) returns int value }
var c Counter(0) c.increment() c.increment() print "the counter is at `c.get()`"

define Point(x: int, y: int)
{
    function distance_squared(this) returns int
        this.x * this.x + this.y * this.y
}

let p Point(3, 4)
print "the distance squared is `p.distance_squared()`"

define Option union(Some: int, None)

let present Option.Some(42)
let absent  Option.None

; shapes.scaly define Box(width: int, height: int) { function area(this) returns int width * height }
; myprog.scaly module shapes use myprog.shapes.Box ; or: use myprog.shapes.*
let b Box(3, 4) if b.area() = 12 print("area is 12")
